function createCompanion(){if(heroId!=='lingya')return;document.body.classList.add('has-companion');companionMesh=makeBadger();scene.add(companionMesh);companion=new BeastCompanion({player:()=>player,stats:()=>weaponStats(player),active:()=>state==='playing',foes:()=>[...enemies,...(boss?.alive?[boss]:[])],visible:visibleEnemy,clear:(ax,az,bx,bz)=>!world.obstacles.some(o=>segmentDistance(o.x,o.z,ax,az,bx,bz)<o.r+.12),move:(p,dx,dz)=>{const slow=terrainAt(world,p.x,p.z,'wolf').speed,ox=p.x,oz=p.z;moveActor(world,p,dx*slow,dz*slow,.30);if(Math.hypot(p.x-ox,p.z-oz)<.001)for(const turn of[.85,-.85,1.35,-1.35]){const x=dx*Math.cos(turn)+dz*Math.sin(turn),z=dz*Math.cos(turn)-dx*Math.sin(turn);if(clearAt(world,p.x+x,p.z+z,.31)){moveActor(world,p,x*slow,z*slow,.30);break;}}},home:()=>{for(const r of[1.2,2,3,4])for(let i=0;i<12;i++){const a=i*Math.PI/6,x=player.x+Math.sin(a)*r,z=player.z+Math.cos(a)*r;if(clearAt(world,x,z,.32)&&!world.patches.some(q=>q.kind==='vent'&&Math.hypot(q.x-x,q.z-z)<q.r+.5)&&![...enemies,...(boss?.alive?[boss]:[])].some(e=>e.alive&&Math.hypot(e.x-x,e.z-z)<e.size+1)&&!zones.some(q=>q.kind!=='meteor'&&q.life>0&&Math.hypot(q.x-x,q.z-z)<q.r+.5))return{x,z};}return null;},damage:hurtEnemy,onHit:e=>{heroSkills.newHeroes.petHit(e);weaponRouteEffect(vfx,weaponStats(player),'pet',e.x,e.z,companion.angle,{empowered:e.lingyaMark>companion.now,targetSize:e.size});},fx:companionFX});companionMesh.position.set(companion.x,0,companion.z);}
