function showPauseDialog(){dialog('在林间歇一会儿','当前生命、技能与探索进度已保留。攻击方式：'+(attackMode==='auto'?(touch?'自动瞄准，按住攻击键出手':'自动瞄准并攻击'):'手动瞄准并攻击')+'。<br>'+weaponReachText(weaponStats(player))+'<br>空格跳跃 · Ctrl 下蹲 · Shift 闪避（手机使用对应按钮）。跳过震地、低矮冰霜；下蹲躲沙卫高位刺击，毒雾和高大突刺仍危险。<br>自动瞄准寻找视野内目标；已发射攻击按实际路径与射程结算。',[['继续远征',resume],...(!touch&&adventureCamera.mode==='first'?[[firstMouseHidden?'战斗鼠标：隐藏 · 点击改为显示':'战斗鼠标：显示 · 点击改为隐藏',()=>{setFirstMouseHidden(!firstMouseHidden);showPauseDialog();}]]:[]),...(player.pending>0?[["选择成长 · "+player.pending+" 次",()=>{resume();upgrade(true);}]]:[]),['查看探索地图',showExplorationMap],[attackMode==='auto'?'切换为手动瞄准':touch?'切换为自动瞄准':'切换为自动攻击',()=>{setAttackMode(attackMode==='auto'?'manual':'auto');showPauseDialog();}],['结束本局',()=>dialog('结束这次远征？','返回准备界面将结束当前对局。',[['返回暂停',()=>{state='playing';pause();}],['确认结束',menu]])]]);}
