function closestAutoTarget(range){let best=null,bestScore=Infinity;const consider=e=>{if(!visibleEnemy(e))return;const fromY=(player.y||0)+eyeHeight*.76*(1-.45*(player.crouch||0)),toY=(e.y||0)+(e.height||1.4)*.55,distance=(e.x-player.x)**2+(e.z-player.z)**2+(toY-fromY)**2;if(distance>=range*range||world.obstacles.some(o=>segmentHitsBody(player.x,fromY,player.z,e.x,toY,e.z,o,.12)))return;const score=distance*(e===autoTargetLock&&distance>9?.82:1);if(score<bestScore){best=e;bestScore=score;}};for(const e of enemies)consider(e);if(boss)consider(boss);if(!best)for(const o of world.breakables||[]){const distance=Math.hypot(o.x-player.x,o.z-player.z);if(o.state!=='standing'||distance>=range||!visibleCombatPoint(o.x,o.z)||world.obstacles.some(b=>b!==o&&segmentDistance(b.x,b.z,player.x,player.z,o.x,o.z)<b.r))continue;if(enemies.some(e=>e.alive&&Math.hypot(e.x-player.x,e.z-player.z)<range+5&&Math.hypot(e.x-player.x,e.z-player.z)>distance&&segmentDistance(o.x,o.z,player.x,player.z,e.x,e.z)<o.r+.1)){best=o;break;}}autoTargetLock=best;return best;}
