function updateVents(){if(mapId!=='ash'&&!world.regions)return;for(const vent of world.patches){if(vent.kind!=='vent')continue;const phase=(time+vent.phase)%4,warning=phase>=2&&phase<3.25,active=phase>=3.25&&phase<3.85;if(warning&&!vent.warned&&Math.hypot(player.x-vent.x,player.z-vent.z)<18){sound.threat('wind');vfx.particle('smoke',0x937b70,vent.x,.2,vent.z,{life:1.2,size:[vent.r*.4,.25,vent.r*.4],velocity:[0,.65,0],opacity:.55,additive:false});}vent.warned=warning;vent.marker.visible=warning||active;vent.marker.material.color.set(active?0xff603c:0xffc16d);vent.marker.material.opacity=active?.8:.58;if(active&&!vent.wasActive){vent.hitPlayer=false;vent.hitPet=false;vent.hitEnemies=new Set();vfx.fire(vent.x,vent.z,vent.r*.65);if(Math.hypot(player.x-vent.x,player.z-vent.z)<14)sound.tone(115,.25,.13,'sine',45);}if(active){if(!vent.hitPet&&companion?.alive&&Math.hypot(companion.x-vent.x,companion.z-vent.z)<vent.r){vent.hitPet=true;companion.takeDamage(12);}if(!vent.hitPlayer&&Math.hypot(player.x-vent.x,player.z-vent.z)<vent.r){vent.hitPlayer=true;hitPlayer(12,vent.x,vent.z,'vent');if(state!=='playing')return;}for(const e of [...enemies,...(boss?.alive?[boss]:[])])if(e.alive&&!vent.hitEnemies.has(e)&&Math.hypot(e.x-vent.x,e.z-vent.z)<vent.r){vent.hitEnemies.add(e);hurtEnemy(e,e===boss?18:36);if(state!=='playing')return;}}vent.wasActive=active;}}
