function mobilityCeiling(){
 if(!world.overhead?.meshes?.length)return Infinity;
 let ceiling=Infinity;const top=(player.y||0)+player.standHeight+1.2;
 for(const [dx,dz]of [[0,0],[.3,0],[-.3,0],[0,.3],[0,-.3]]){const low={x:player.x+dx,y:.05,z:player.z+dz},high={...low,y:top};const hit=world.overhead.firstHit(low,high)||world.overhead.firstHit(high,low);if(hit)ceiling=Math.min(ceiling,hit.point.y-.08);}
 return ceiling;
}
function jump(){if(state!=='playing')return;if(mobilityCeiling()<bodyHeight(player)+.15)return;if(beginJump(player,terrainAt(world,player.x,player.z).depth)){renderer.shadowMap.needsUpdate=true;}}
function clearMobilityInput(){touchCrouch=false;$('#crouch').setAttribute('aria-pressed','false');}
